  folder: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAOCAYAAAAmL5yKAAAAP0lEQVR4nGNgGPKAMcqG4T8uyWVHGBgpMoAoF/z/sI8yA6JsGP4vnWhDlubo/CMMTJTYzsDAMGoANQygOCEBAOx2Dn3OeaF1AAAAAElFTkSuQmCC",
