  book: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAOCAYAAAAmL5yKAAAAgUlEQVR4nO2Pyw1AQBRFD1GCEix0YKOEV4TSFDElzEYH0wM9sHGZ+ASRWLnJW7yXe05m4GUSgBxGgGHe70RMqoMra3IY49kC8biyBiBToXItPdBZs0AW/CIRcPoFFSrXQiSy4E9hC359gSJQIoriEFZ2gq3oKul15Rd8J7DgH4HqT6L3KIS/LDS7AAAAAElFTkSuQmCC",
