/* ==========================================================================
   ANDRE95 — shared desktop behavior for index.html / about.html / contact.html
   Vanilla JS, no dependencies. GIFS{} (see top of this file) holds every
   pixel-art asset as a base64 data URI so all five files stay self-contained.
   ========================================================================== */
(function(){
  "use strict";

  /* ---------------------------------------------------------- lazy gifs */
  // Real lazy-loading: <img data-gif="key" class="lazy-gif"> only gets its
  // src set once it scrolls into view (or immediately if IO is unsupported).
  function hydrateImg(img){
    var key = img.getAttribute("data-gif");
    if (key && GIFS[key]) { img.src = GIFS[key]; }
    img.removeAttribute("data-gif");
    img.classList.remove("lazy-gif");
  }
  function initLazyGifs(root){
    var imgs = (root || document).querySelectorAll("img.lazy-gif[data-gif]");
    if (!("IntersectionObserver" in window)) {
      imgs.forEach(hydrateImg);
      return;
    }
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if (entry.isIntersecting) {
          hydrateImg(entry.target);
          io.unobserve(entry.target);
        }
      });
    }, { rootMargin: "80px" });
    imgs.forEach(function(img){ io.observe(img); });
  }

  /* -------------------------------------------------------------- clock */
  function tickClock(){
    var el = document.getElementById("clock");
    if (!el) return;
    var d = new Date();
    var h = d.getHours() % 12 || 12;
    var m = String(d.getMinutes()).padStart(2, "0");
    var ap = d.getHours() >= 12 ? "PM" : "AM";
    el.textContent = h + ":" + m + " " + ap;
  }

  /* ---------------------------------------------------------- z-order --- */
  var zTop = 20;
  function focusWindow(win){
    document.querySelectorAll(".window").forEach(function(w){ w.classList.remove("is-active"); });
    win.classList.add("is-active");
    zTop += 1;
    win.style.zIndex = zTop;
    syncTaskbar();
  }

  /* ------------------------------------------------------------ windows */
  function openWindow(id, opts){
    var win = document.getElementById(id);
    if (!win) return;
    opts = opts || {};
    if (!win.style.left) {
      var count = document.querySelectorAll(".window.is-open").length;
      win.style.left = (24 + count * 26) + "px";
      win.style.top = (54 + count * 24) + "px";
    }
    win.classList.add("is-open");
    win.classList.remove("is-minimized");
    initLazyGifs(win);
    focusWindow(win);
    var menu = document.getElementById("start-menu");
    if (menu) menu.classList.remove("is-open");
  }
  function closeWindow(id){
    var win = document.getElementById(id);
    if (!win) return;
    win.classList.remove("is-open", "is-maximized");
    syncTaskbar();
  }
  function minimizeWindow(id){
    var win = document.getElementById(id);
    if (!win) return;
    win.classList.add("is-minimized");
    syncTaskbar();
  }
  function toggleMaximize(id){
    var win = document.getElementById(id);
    if (!win) return;
    win.classList.toggle("is-maximized");
  }
  window.ANDRE95 = window.ANDRE95 || {};
  ANDRE95.openWindow = openWindow;
  ANDRE95.closeWindow = closeWindow;

  function syncTaskbar(){
    var list = document.getElementById("task-list");
    if (!list) return;
    list.innerHTML = "";
    document.querySelectorAll(".window.is-open").forEach(function(win){
      var tab = document.createElement("button");
      tab.className = "task-tab bevel-btn";
      var active = win.classList.contains("is-active") && !win.classList.contains("is-minimized");
      if (active) tab.classList.add("is-down");
      var titleEl = win.querySelector(".t-text");
      tab.textContent = titleEl ? titleEl.textContent : win.id;
      tab.addEventListener("click", function(){
        if (win.classList.contains("is-minimized")) {
          win.classList.remove("is-minimized");
          focusWindow(win);
        } else if (win.classList.contains("is-active")) {
          minimizeWindow(win.id);
        } else {
          focusWindow(win);
        }
      });
      list.appendChild(tab);
    });
  }

  /* ------------------------------------------------------------ dragging */
  function makeDraggable(win){
    var bar = win.querySelector(".titlebar");
    if (!bar) return;
    var dragging = false, offX = 0, offY = 0;

    function start(clientX, clientY){
      if (win.classList.contains("is-maximized")) return;
      dragging = true;
      var rect = win.getBoundingClientRect();
      offX = clientX - rect.left;
      offY = clientY - rect.top;
      focusWindow(win);
    }
    function move(clientX, clientY){
      if (!dragging) return;
      var maxX = window.innerWidth - 60;
      var maxY = window.innerHeight - 40;
      var x = Math.min(Math.max(clientX - offX, -20), maxX);
      var y = Math.min(Math.max(clientY - offY, 0), maxY);
      win.style.left = x + "px";
      win.style.top = y + "px";
    }
    function end(){ dragging = false; }

    bar.addEventListener("mousedown", function(e){
      if (e.target.closest(".title-btn")) return;
      start(e.clientX, e.clientY);
      e.preventDefault();
    });
    window.addEventListener("mousemove", function(e){ move(e.clientX, e.clientY); });
    window.addEventListener("mouseup", end);

    bar.addEventListener("touchstart", function(e){
      if (e.target.closest(".title-btn")) return;
      var t = e.touches[0];
      start(t.clientX, t.clientY);
    }, { passive: true });
    bar.addEventListener("touchmove", function(e){
      var t = e.touches[0];
      move(t.clientX, t.clientY);
    }, { passive: true });
    bar.addEventListener("touchend", end);

    win.addEventListener("mousedown", function(){ focusWindow(win); });
  }

  /* ------------------------------------------------------------ start menu */
  function initStartMenu(){
    var btn = document.getElementById("start-btn");
    var menu = document.getElementById("start-menu");
    if (!btn || !menu) return;
    btn.addEventListener("click", function(){
      menu.classList.toggle("is-open");
    });
    document.addEventListener("click", function(e){
      if (!menu.contains(e.target) && e.target !== btn && !btn.contains(e.target)) {
        menu.classList.remove("is-open");
      }
    });
  }

  /* --------------------------------------------------------------- BSOD */
  function initShutdown(){
    document.querySelectorAll("[data-shutdown]").forEach(function(el){
      el.addEventListener("click", function(){
        var bsod = document.getElementById("bsod");
        if (bsod) bsod.classList.add("is-open");
        var menu = document.getElementById("start-menu");
        if (menu) menu.classList.remove("is-open");
      });
    });
    var reboot = document.getElementById("bsod-reboot");
    if (reboot) reboot.addEventListener("click", function(){
      document.getElementById("bsod").classList.remove("is-open");
    });
  }

  /* -------------------------------------------------------------- modals */
  function initModals(){
    document.querySelectorAll("[data-open-modal]").forEach(function(el){
      el.addEventListener("click", function(){
        var id = el.getAttribute("data-open-modal");
        var m = document.getElementById(id);
        if (m) m.classList.add("is-open");
      });
    });
    document.querySelectorAll("[data-close-modal]").forEach(function(el){
      el.addEventListener("click", function(){
        el.closest(".modal-backdrop").classList.remove("is-open");
      });
    });
  }

  /* --------------------------------------------------------------- flags */
  var STRINGS = {
    en: { spelling: "COLOR", greet: "welcome to the site!!" },
    uk: { spelling: "COLOUR", greet: "welcome to the site, cheers!" },
    jp: { spelling: "COLOR", greet: "ようこそ (welcome)!" }
  };
  function initFlags(){
    var flags = document.querySelectorAll(".flag-btn");
    if (!flags.length) return;
    flags.forEach(function(btn){
      btn.addEventListener("click", function(){
        flags.forEach(function(b){ b.setAttribute("aria-pressed", "false"); });
        btn.setAttribute("aria-pressed", "true");
        var region = btn.getAttribute("data-region");
        var s = STRINGS[region] || STRINGS.en;
        document.querySelectorAll("[data-i18n-spelling]").forEach(function(n){ n.textContent = s.spelling; });
        document.querySelectorAll("[data-i18n-greet]").forEach(function(n){ n.textContent = s.greet; });
        document.documentElement.setAttribute("lang", region === "jp" ? "en" : "en");
      });
    });
  }

  /* --------------------------------------------------------- guestbook */
  function initGuestbook(){
    var form = document.querySelector("form.guestbook");
    if (!form) return;
    form.addEventListener("submit", function(e){
      e.preventDefault();
      var msg = form.querySelector(".field-msg");
      if (msg) {
        msg.textContent = "* Entry saved to guestbook.dat — thanks for signing, " +
          (form.name.value || "mystery visitor") + "! *";
        msg.classList.add("is-shown");
      }
      form.reset();
    });
  }

  /* ----------------------------------------------------------- counter */
  function initCounter(){
    var el = document.getElementById("hit-count");
    if (!el) return;
    var n = parseInt(localStorage.getItem("andre95-hits") || "133780", 10) + 1;
    try { localStorage.setItem("andre95-hits", String(n)); } catch (err) { /* ignore */ }
    el.textContent = String(n).padStart(6, "0");
  }

  /* --------------------------------------------------------- desktop icons */
  function initIcons(){
    document.querySelectorAll(".desktop-icon[data-open]").forEach(function(icon){
      icon.addEventListener("click", function(){
        openWindow(icon.getAttribute("data-open"));
      });
    });
    document.querySelectorAll("[data-nav-open]").forEach(function(el){
      el.addEventListener("click", function(e){
        var id = el.getAttribute("data-nav-open");
        if (document.getElementById(id)) {
          e.preventDefault();
          openWindow(id);
        }
        // else: real link (about.html / contact.html) — let it navigate.
      });
    });
    document.querySelectorAll("[data-close]").forEach(function(el){
      el.addEventListener("click", function(){ closeWindow(el.getAttribute("data-close")); });
    });
    document.querySelectorAll("[data-min]").forEach(function(el){
      el.addEventListener("click", function(){ minimizeWindow(el.getAttribute("data-min")); });
    });
    document.querySelectorAll("[data-max]").forEach(function(el){
      el.addEventListener("click", function(){ toggleMaximize(el.getAttribute("data-max")); });
    });
  }

  /* -------------------------------------------------------------- init */
  document.addEventListener("DOMContentLoaded", function(){
    initLazyGifs(document);
    document.querySelectorAll(".window").forEach(makeDraggable);
    initIcons();
    initStartMenu();
    initShutdown();
    initModals();
    initFlags();
    initGuestbook();
    initCounter();
    tickClock();
    setInterval(tickClock, 15000);

    // Auto-open a window if the URL says so (?open=about) or hash (#projects)
    var params = new URLSearchParams(location.search);
    var openId = params.get("open") || location.hash.replace("#", "");
    if (openId && document.getElementById(openId)) {
      openWindow(openId);
    }

    document.querySelectorAll(".project-card[data-detail]").forEach(function(card){
      card.addEventListener("click", function(){
        var box = card.querySelector(".project-detail");
        if (box) box.classList.toggle("hidden");
      });
    });
  });
})();
